import { RESOLVE_WAIT_MS, resolveWaitMs, resolveStageStarts } from './resolve_stage_timing.js';
import { renderStageStacks } from './resolve_stacks.js';
import { stageMotionAt, renderStageMotion } from './resolve_stage_motion.js';
import { pickStageLayout } from './resolve_stage_layout.js';
import { renderResolveStage, fitResolveStage, isOneSidedPresentation, currentStageLayout } from './resolve_stage.js';
import { store } from '../core/BattleStore.js';
import { skillNameFromCommands } from '../utils/SkillUtils.js';
import { eventBus } from '../core/EventBus.js';
import { socketClient } from '../core/SocketClient.js';
import { resolveStageTiming, playResolveStageFx, isDiceDamageSource, resolveOutcomePlan } from './resolve_flow_fx.js';

class ResolveFlowPanel {
    constructor() {
        this._unsubscribe = null;
        this._unsubscribeAdvanceEvent = null;
        this._unsubscribeStartRequestedEvent = null;
        this._unsubscribeBattleErrorEvent = null;
        this._panelId = 'resolve-flow-panel';
        this._initialized = false;
        this._traceSeen = new Set();
        this._displayIndexByKey = new Map();
        this._displayIndexCursor = 0;
        this._presentedStepCount = 0;
        this._baseStepTotal = 0;
        this._playQueue = [];
        this._activeStep = null;
        this._roundKey = null;
        this._roundNumber = 0;
        this._stepTimer = null;
        this._tickTimer = null;
        this._motionFrame = null;
        this._stepStartedAt = 0;
        this._lastStageKey = null;
        this._unsubscribeStage = null;
        this._liveGemPreludeTimestamp = null;
        this._gemPortraits = new Map();
        this._introDurationMs = 1600;
        this._renderedStepKey = null;
        this._introShownRounds = new Set();
        this._waitingForAdvance = false;
        this._autoAdvanceEnabled = false;
        this._autoAdvanceDelayMs = RESOLVE_WAIT_MS;
        this._pendingAdvanceTimer = null;
        this._advanceRequestPending = false;
        this._advanceRequestPendingTimer = null;
        this._pendingSyncedAdvanceCount = 0;
        this._completionEmittedRounds = new Set();
        this._roundSawResolvePhase = false;
        this._powerRevealSePlayedKeys = new Set();
        this._resetNextMatchClock = false;
        this._waitingForFirstTrace = false;
        this._resolveStartPending = false;
        this._resolveOpeningRoundKey = null;
        this._onResize = () => { if (this._activeStep) this._renderStep(store.state || {}); };
    }

    initialize() {
        if (this._initialized) {
            this._onStateUpdated(store.state || {});
            return true;
        }
        this._unsubscribe = store.subscribe((state) => this._onStateUpdated(state || {}));
        this._unsubscribeStage = eventBus.on('battle:resolve:flow:stage', (payload) => {
            if (payload.stepKey === this._traceKey(this._activeStep)) {
                playResolveStageFx(this, payload, store.state || {});
            }
        });
        this._unsubscribeLiveGemPrelude = eventBus.on('battle:phase:will-change', (payload) => {
            if (payload.from === 'select' && payload.to === 'resolve_mass') {
                this._liveGemPreludeTimestamp = payload.gem_prelude_timestamp ?? null;
            }
        });
        this._unsubscribeDisconnect = eventBus.on('battle:connection:lost', () => {
            this._liveGemPreludeTimestamp = null;
            window.Fx?.cancelSounds?.();
        });
        this._unsubscribeAdvanceEvent = eventBus.on('battle:resolve:flow:advance', (payload) => {
            this._onSyncedAdvanceSignal(payload || {});
        });
        this._unsubscribeStartRequestedEvent = eventBus.on('battle:resolve:start:requested', (payload) => {
            this._onResolveStartRequested(payload || {});
        });
        this._unsubscribeBattleErrorEvent = eventBus.on('battle:error', (payload) => {
            this._onResolveStartError(payload || {});
        });
        this._initialized = true;
        if (typeof window !== 'undefined') window.addEventListener('resize', this._onResize);
        this._onStateUpdated(store.state || {});
        console.log('ResolveFlowPanel initialized');
        return true;
    }

    destroy() {
        if (typeof window !== 'undefined') window.removeEventListener('resize', this._onResize);
        if (this._unsubscribeStage) this._unsubscribeStage();
        this._unsubscribeStage = null;
        this._unsubscribeLiveGemPrelude?.();
        this._unsubscribeDisconnect?.();
        this._liveGemPreludeTimestamp = null;
        this._gemPortraits.clear();
        if (this._unsubscribe) {
            this._unsubscribe();
            this._unsubscribe = null;
        }
        if (this._unsubscribeAdvanceEvent) {
            this._unsubscribeAdvanceEvent();
            this._unsubscribeAdvanceEvent = null;
        }
        if (this._unsubscribeStartRequestedEvent) {
            this._unsubscribeStartRequestedEvent();
            this._unsubscribeStartRequestedEvent = null;
        }
        if (this._unsubscribeBattleErrorEvent) {
            this._unsubscribeBattleErrorEvent();
            this._unsubscribeBattleErrorEvent = null;
        }
        this._stopPlayback();
        this._traceSeen.clear();
        this._displayIndexByKey.clear();
        this._displayIndexCursor = 0;
        this._presentedStepCount = 0;
        this._baseStepTotal = 0;
        this._playQueue = [];
        this._activeStep = null;
        this._roundKey = null;
        this._roundNumber = 0;
        this._renderedStepKey = null;
        this._introShownRounds.clear();
        this._waitingForAdvance = false;
        this._autoAdvanceEnabled = false;
        this._clearPendingAdvanceTimer();
        this._clearAdvanceRequestPending();
        this._pendingSyncedAdvanceCount = 0;
        this._completionEmittedRounds.clear();
        this._roundSawResolvePhase = false;
        this._powerRevealSePlayedKeys.clear();
        this._resetNextMatchClock = false;
        this._waitingForFirstTrace = false;
        this._resolveStartPending = false;
        this._resolveOpeningRoundKey = null;
        this._initialized = false;
        const panel = document.getElementById(this._panelId);
        if (panel) panel.remove();
    }

    _escape(text) {
        return String(text || '')
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;')
            .replace(/'/g, '&#39;');
    }

    _kindLabel(kind) {
        const map = {
            clash: '\u30de\u30c3\u30c1',
            one_sided: '\u4e00\u65b9\u653b\u6483',
            hard_attack: '\u5f37\u786c\u653b\u6483',
            mass_individual: '\u5e83\u57df-\u500b\u5225',
            mass_summation: '\u5e83\u57df-\u5408\u7b97',
            fizzle: '\u4e0d\u767a',
            evade_insert: '\u56de\u907f\u5dee\u3057\u8fbc\u307f'
        };
        return map[String(kind || '')] || String(kind || 'unknown');
    }

    _actorNameById(actorId, state) {
        if (!actorId) return null;
        const chars = Array.isArray(state.characters) ? state.characters : [];
        const hit = chars.find((c) => String(c?.id || '') === String(actorId));
        if (hit && hit.name) return String(hit.name);
        return String(actorId);
    }

    _characterById(actorId, state) {
        if (!actorId) return null;
        const chars = Array.isArray(state?.characters) ? state.characters : [];
        return chars.find((c) => String(c?.id || '') === String(actorId)) || null;
    }

    _actorVisualMeta(actorId, state, fallbackName = null) {
        const char = this._characterById(actorId, state);
        const name = char?.name
            ? String(char.name)
            : String(fallbackName || actorId || '-');
        const image = char?.image || char?.imageOriginal || null;
        return {
            actorId: actorId ? String(actorId) : null,
            name,
            image: image ? String(image) : null
        };
    }

    _preparePendingGemPortraits(state) {
        for (const row of state.battle_state?.pending_gem_blessings || []) {
            this._readyGemPortrait(row.actor_id, state);
        }
    }

    _readyGemPortrait(actorId, state) {
        const { image: url } = this._actorVisualMeta(actorId, state);
        if (!url) return null;
        const previous = this._gemPortraits.get(actorId);
        if (previous?.url === url) {
            return previous.ready && !previous.image.isConnected ? previous.image : null;
        }
        const image = new Image();
        const record = { url, image, ready: false };
        this._gemPortraits.set(actorId, record);
        image.decoding = 'async';
        image.src = url;
        image.decode?.().then(() => { record.ready = true; }, () => {});
        return null;
    }

    _slotActorId(slotId, state) {
        if (!slotId) return null;
        const slots = state?.slots || {};
        const slot = slots[String(slotId)] || null;
        return slot?.actor_id || slot?.actor_char_id || null;
    }

    _slotLabel(slotId, state) {
        if (!slotId) return '-';
        const slots = state?.slots || {};
        const slot = slots[String(slotId)] || {};
        const actorId = slot?.actor_id || slot?.actor_char_id || null;
        const actorName = this._actorNameById(actorId || slotId, state) || String(slotId);
        const indexRaw = Number(slot?.index_in_actor);
        if (Number.isFinite(indexRaw)) {
            return `${actorName} #${indexRaw + 1}`;
        }
        return actorName;
    }

    _tiebreakNoteForStep(step, state) {
        const groups = Array.isArray(state?.tiebreak) ? state.tiebreak : [];
        if (groups.length === 0) return '';
        const relevantSlotIds = [step?.attackerSlotId, step?.defenderSlotId]
            .filter(Boolean)
            .map((slotId) => String(slotId));
        if (relevantSlotIds.length === 0) return '';
        const matched = groups.find((group) => {
            const slotIds = Array.isArray(group?.group) ? group.group.map((slotId) => String(slotId)) : [];
            return relevantSlotIds.some((slotId) => slotIds.includes(slotId));
        });
        if (!matched) return '';
        const rolls = (matched.rolls && typeof matched.rolls === 'object') ? matched.rolls : {};
        const details = (Array.isArray(matched.group) ? matched.group : [])
            .map((slotId) => {
                const label = this._slotLabel(slotId, state);
                const roll = rolls[slotId];
                return `${label}:${roll ?? '-'}`;
            })
            .join(' / ');
        const initiative = matched.initiative ?? '-';
        return `\u540c\u901f\u5224\u5b9a SPD:${initiative} | ${details}`;
    }

    _actorNameFromStep(step, state, side) {
        if (!step) return '-';
        const slotKey = side === 'attacker' ? step.attackerSlotId : step.defenderSlotId;
        const actorKey = side === 'attacker' ? step.attackerActorId : step.defenderActorId;
        const fromSlot = this._slotActorId(slotKey, state);
        if (side === 'defender' && String(step.kind) === 'mass_summation' && !fromSlot && !actorKey) {
            return '\u9632\u885b\u5074\u5168\u4f53';
        }
        const name = this._actorNameById(fromSlot || actorKey, state);
        return name || '-';
    }

    _roundStateKey(state) {
        return `${String(state?.battle_id || '')}:${Number(state?.round || 0)}`;
    }

    _isResolvePhase(phase) {
        return phase === 'resolve_mass' || phase === 'resolve_single';
    }

    _isPlaybackPhase(phase) {
        return this._isResolvePhase(phase) || phase === 'round_end';
    }

    _isResolvePresentationActive(phase) {
        return this._isResolvePhase(phase)
            || (phase === 'select' && this._resolveStartPending);
    }

    _isResolvePresentationCompleted(state) {
        return String(state?.resolvePresentation?.status || '') === 'completed';
    }

    _shouldWaitForFirstTrace(state) {
        const phase = String(state?.phase || '');
        if (
            this._resolveOpeningRoundKey
            && this._resolveOpeningRoundKey === this._roundStateKey(state)
            && !this._isResolvePresentationCompleted(state)
        ) {
            return true;
        }
        if (this._isResolvePresentationActive(phase)) return true;
        // battle_round_finished arrives before the finalized presentation
        // snapshot. Keep the intro visible during that transient round_end.
        return phase === 'round_end' && !this._isResolvePresentationCompleted(state);
    }

    _onResolveStartRequested(payload) {
        const state = store.state || {};
        if (String(state.phase || '') !== 'select') return;
        const requestedRound = this._toNumber(payload?.round, this._toNumber(state.round, 0));
        if (requestedRound !== this._toNumber(state.round, 0)) return;
        this._resolveStartPending = true;
        const roundKey = this._roundStateKey(state);
        this._resolveOpeningRoundKey = roundKey;
        this._enqueueBattleStartIntro(roundKey);
        if (!this._activeStep && this._playQueue.length > 0) {
            this._playNextStep({ forceLocalClock: true });
        } else if (this._activeStep) {
            this._renderStep(state);
        }
    }

    _cancelPendingResolveStart() {
        if (!this._resolveStartPending) return;
        this._resolveStartPending = false;
        this._stopPlayback();
        this._playQueue = [];
        this._activeStep = null;
        this._waitingForFirstTrace = false;
        this._resolveOpeningRoundKey = null;
        this._introShownRounds.delete(this._roundKey);
        this._removePanel();
    }

    _onResolveStartError() {
        // SocketClient emits this event for a newly received battle_error.
        // Do not infer request failure from the persistent Store field because it
        // may contain an error raised before the current resolve-start request.
        this._cancelPendingResolveStart();
    }

    _toNumber(value, fallback = 0) {
        const n = Number(value);
        return Number.isFinite(n) ? n : fallback;
    }

    _detectIsGM(state) {
        if (typeof window === 'undefined') return true;
        const attr = window.currentUserAttribute;
        const role = window.currentUserRole;
        const username = window.currentUsername || window.currentUserName || '';
        const stateAttr = state?.current_user_attribute || state?.user_attribute || null;
        const knownGM =
            attr === 'GM' ||
            role === 'GM' ||
            stateAttr === 'GM' ||
            (typeof username === 'string' && username.includes('(GM)'));
        const hasAnyRoleSignal =
            attr !== undefined ||
            role !== undefined ||
            stateAttr !== null ||
            (typeof username === 'string' && username.length > 0);
        return knownGM || !hasAnyRoleSignal;
    }

    _canDriveResolveFlow(state) {
        const presentation = state?.resolvePresentation || null;
        const controllerUserId = presentation?.controller_user_id || null;
        const currentUserId = (typeof window !== 'undefined') ? window.currentUserId : null;
        if (controllerUserId) {
            return !!currentUserId && String(currentUserId) === String(controllerUserId);
        }
        return this._detectIsGM(state);
    }

    _canClaimResolveFlow(state) {
        return !this._canDriveResolveFlow(state) && this._detectIsGM(state);
    }

    _stepDuration(step) {
        if (this._isIntroStep(step)) return this._introDurationMs;
        return resolveStageTiming(step).reduce((sum, row) => sum + row.ms, 0);
    }

    _clearPendingAdvanceTimer() {
        if (this._pendingAdvanceTimer) {
            clearTimeout(this._pendingAdvanceTimer);
            this._pendingAdvanceTimer = null;
        }
    }

    _clearAdvanceRequestPending() {
        this._advanceRequestPending = false;
        if (this._advanceRequestPendingTimer) {
            clearTimeout(this._advanceRequestPendingTimer);
            this._advanceRequestPendingTimer = null;
        }
    }

    _markAdvanceRequestPending() {
        this._clearAdvanceRequestPending();
        this._advanceRequestPending = true;
        this._advanceRequestPendingTimer = setTimeout(() => {
            this._advanceRequestPending = false;
            this._advanceRequestPendingTimer = null;
            this._renderStep(store.state || {});
        }, 2500);
    }

    _resolveActiveRoomId(state) {
        const fromState = state?.room_id || state?.room_name || null;
        if (fromState) return String(fromState);
        if (typeof window !== 'undefined' && window.currentRoomName) return String(window.currentRoomName);
        return null;
    }

    _buildAdvanceRequestPayload(state) {
        const roomId = this._resolveActiveRoomId(state);
        const rawStepIndex = Number(this._activeStep?.rawStepIndex);
        const displayStepIndex = Number(this._activeStep?.stepIndex);
        const stepIndex = Number.isFinite(rawStepIndex)
            ? rawStepIndex
            : (Number.isFinite(displayStepIndex) ? displayStepIndex : null);
        return {
            room_id: roomId || null,
            battle_id: state?.battle_id || null,
            round: this._toNumber(state?.round, 0),
            expected_step_index: stepIndex,
            expected_revision: this._toNumber(state?.resolvePresentation?.revision, 0)
        };
    }

    _matchesSyncedAdvanceSignal(payload, state) {
        const data = (payload && typeof payload === 'object') ? payload : {};
        const roomId = this._resolveActiveRoomId(state);
        const payloadRoom = data.room_id || data.room_name || data.room || null;
        if (roomId && payloadRoom && String(roomId) !== String(payloadRoom)) return false;
        const battleId = state?.battle_id || null;
        if (battleId && data.battle_id && String(battleId) !== String(data.battle_id)) return false;
        const payloadRound = (data.round !== undefined && data.round !== null) ? this._toNumber(data.round, NaN) : NaN;
        const stateRound = this._toNumber(state?.round, NaN);
        if (Number.isFinite(payloadRound) && Number.isFinite(stateRound) && payloadRound !== stateRound) return false;
        const payloadStep = this._toNumber(data.expected_step_index, NaN);
        const activeStep = this._toNumber(this._activeStep?.rawStepIndex, NaN);
        if (Number.isFinite(payloadStep) && Number.isFinite(activeStep) && payloadStep !== activeStep) return false;
        return true;
    }

    _canCompleteCurrentRound(state) {
        const stateNow = state || store.state || {};
        const phase = String(stateNow?.phase || '');
        if (phase !== 'round_end') return false;
        const roundKey = this._roundStateKey(stateNow);
        if (!roundKey) return false;
        // Prevent false completion on reconnect/round-start transient round_end snapshots.
        return this._roundSawResolvePhase || this._introShownRounds.has(roundKey) || this._presentedStepCount > 0;
    }

    _emitResolveFlowCompleted(state) {
        const stateNow = state || store.state || {};
        if (!this._canCompleteCurrentRound(stateNow)) return;
        const roundKey = this._roundStateKey(stateNow);
        if (!roundKey || this._completionEmittedRounds.has(roundKey)) return;
        this._completionEmittedRounds.add(roundKey);
        const payload = {
            room_id: this._resolveActiveRoomId(stateNow),
            battle_id: stateNow?.battle_id || null,
            round: this._toNumber(stateNow?.round, 0),
            round_key: roundKey
        };
        eventBus.emit('battle:resolve:flow:completed', payload);
    }

    _emitResolveFlowStepFinished(step, state) {
        const stateNow = state || store.state || {};
        if (!step || this._isIntroStep(step)) return;
        const payload = {
            room_id: this._resolveActiveRoomId(stateNow),
            battle_id: stateNow?.battle_id || null,
            round: this._toNumber(stateNow?.round, 0),
            step_index: this._toNumber(step?.stepIndex, -1),
            step_display_index: this._toNumber(step?.displayIndex, -1),
            kind: String(step?.kind || 'unknown'),
            key: this._traceKey(step) || null
        };
        eventBus.emit('battle:resolve:flow:step-finished', payload);
    }

    _flushCurrentStepDeferredLogs() {
        if (!this._activeStep || this._isIntroStep(this._activeStep)) return;
        if (typeof window === 'undefined' || typeof window.flushDeferredResolveByStepKey !== 'function') return;
        const stateNow = store.state || {};
        const payload = {
            room_id: this._resolveActiveRoomId(stateNow),
            battle_id: stateNow?.battle_id || null,
            round: this._toNumber(stateNow?.round, 0),
            step_index: this._toNumber(this._activeStep?.stepIndex, -1),
            step_display_index: this._toNumber(this._activeStep?.displayIndex, -1),
            kind: String(this._activeStep?.kind || 'unknown'),
            key: this._traceKey(this._activeStep) || null
        };
        try {
            window.flushDeferredResolveByStepKey(payload);
        } catch (_e) {
            // no-op
        }
    }

    _scheduleAutoAdvanceIfNeeded(state) {
        if (this._pendingAdvanceTimer) return;
        if (!this._waitingForAdvance || !this._activeStep) return;
        if (this._isIntroStep(this._activeStep)) return;
        // 加護の前置きは、自動進行の設定によらず進行役の端末が次へ進める。
        if (!this._autoAdvanceEnabled && this._activeStep.kind !== 'gem_blessing_prelude') return;
        if (!this._canDriveResolveFlow(state)) return;
        this._pendingAdvanceTimer = setTimeout(() => {
            this._pendingAdvanceTimer = null;
            this._onAdvanceRequested();
        }, Math.max(resolveWaitMs(this._activeStep, this._autoAdvanceDelayMs),
            this._outcomeFxDeadline?.step === this._activeStep ? this._outcomeFxDeadline.atMs - Date.now() : 0));
    }

    _revealStageByElapsed(elapsedMs, step) {
        const timing = resolveStageTiming(step);
        const elapsed = Math.max(0, elapsedMs);
        let end = 0;
        for (const row of timing) {
            end += row.ms;
            if (elapsed < end) return row.stage;
        }
        return timing[timing.length - 1].stage;
    }

    _notifyStage(stepKey, stage, step) {
        const key = `${stepKey}:${stage}`;
        if (this._lastStageKey === key) return;
        this._lastStageKey = key;
        // 前置きのtraceは同期にも含まれる。直前の解決開始の合図と一致したときだけ鳴らす。
        const liveGemPrelude = step.kind === 'gem_blessing_prelude'
            && this._liveGemPreludeTimestamp !== null
            && this._liveGemPreludeTimestamp === step.timestamp;
        const payload = { stepKey, stage, kind: step.kind, outcome: step.outcome };
        if (liveGemPrelude) {
            this._liveGemPreludeTimestamp = null;
            payload.liveGemPrelude = true;
        }
        eventBus.emit('battle:resolve:flow:stage', payload);
    }

    _revealLabel(stage) {
        const labels = {
            names: '名前',
            attack: '攻撃',
            power: '\u5a01\u529b',
            outcome: '\u52dd\u6557'
        };
        return labels[String(stage || '')] || '';
    }

    _rememberPowerSePlayed(stepKey) {
        if (!stepKey) return;
        this._powerRevealSePlayedKeys.add(stepKey);
        if (this._powerRevealSePlayedKeys.size <= 1800) return;
        const keep = Array.from(this._powerRevealSePlayedKeys).slice(-1300);
        this._powerRevealSePlayedKeys.clear();
        keep.forEach((k) => this._powerRevealSePlayedKeys.add(k));
    }

    _tryPlayPowerRevealSe(stepKey, revealStage) {
        if (!stepKey) return;
        const stage = String(revealStage || '');
        if (stage !== 'power' && stage !== 'outcome') return;
        if (this._powerRevealSePlayedKeys.has(stepKey)) return;
        this._rememberPowerSePlayed(stepKey);
        if (typeof window === 'undefined') return;
        const sfx = window.SoundFx;
        if (!sfx || typeof sfx.playDiceRoll !== 'function') return;
        try {
            void sfx.playDiceRoll({ bypassThrottle: true });
        } catch (_e) {
            // Ignore sound errors in UI flow rendering.
        }
    }

    _allSkillData() {
        if (typeof window === 'undefined') return {};
        const all = window.allSkillData;
        return (all && typeof all === 'object') ? all : {};
    }

    _skillById(skillId) {
        if (!skillId) return null;
        const all = this._allSkillData();
        const hit = all[String(skillId)];
        return (hit && typeof hit === 'object') ? hit : null;
    }

    _intentSkillId(state, slotId) {
        if (!slotId) return null;
        const intents = state?.intents || {};
        const intent = intents[String(slotId)] || null;
        if (!intent || typeof intent !== 'object') return null;
        const sid = intent.skill_id || intent.skillId || null;
        return sid ? String(sid) : null;
    }

    _normalizeTraceEntry(rawEntry, fallbackIndex = 0, state = null) {
        const raw = (rawEntry && typeof rawEntry === 'object') ? rawEntry : {};
        const rawStepIndex = (raw.step_index !== undefined && raw.step_index !== null)
            ? this._toNumber(raw.step_index, NaN)
            : NaN;
        const stepIndex = Math.max(0, this._toNumber(fallbackIndex, 0));
        const stepTotalRaw = this._toNumber(raw.step_total, 0);
        const stepTotal = stepTotalRaw > 0 ? stepTotalRaw : 0;
        const attackerSlotId = raw.attacker_slot_id || raw.attacker_slot || null;
        const defenderSlotId = raw.defender_slot_id || raw.defender_slot || null;
        const payload = (raw.outcome_payload && typeof raw.outcome_payload === 'object') ? raw.outcome_payload : {};
        const delegateSummary = (payload.delegate_summary && typeof payload.delegate_summary === 'object')
            ? payload.delegate_summary
            : {};
        const summaryRolls = (delegateSummary.rolls && typeof delegateSummary.rolls === 'object')
            ? delegateSummary.rolls
            : {};
        const rolls = (raw.rolls && typeof raw.rolls === 'object') ? raw.rolls : {};
        const parsedAtk = this._parseSkillFromCommand(rolls.command || summaryRolls.command || '');
        const parsedDef = this._parseSkillFromCommand(rolls.command_b || summaryRolls.command_b || '');
        const attackerSkillId = payload.skill_id || this._intentSkillId(state, attackerSlotId) || parsedAtk.id || null;
        const defenderSkillId = raw.defender_skill_id || this._intentSkillId(state, defenderSlotId) || parsedDef.id || null;
        const attackerSkillData = this._skillById(attackerSkillId);
        const defenderSkillData = this._skillById(defenderSkillId);
        // キャラが付けた名前（チャットパレットの【ID 名前】）を、スキルデータの名前より先に使う。
        const roster = state || store.state || {};
        const ownName = (actorId, slotId, skillId) => skillNameFromCommands(
            this._characterById(actorId || this._slotActorId(slotId, roster), roster), skillId);
        const attackerSkillName = ownName(raw.attacker_actor_id, attackerSlotId, attackerSkillId)
            || this._skillNameFromData(payload.skill)
            || this._skillNameFromData(attackerSkillData)
            || parsedAtk.name
            || null;
        const defenderSkillName = ownName(raw.defender_actor_id || raw.target_actor_id, defenderSlotId, defenderSkillId)
            || this._skillNameFromData(defenderSkillData)
            || parsedDef.name
            || null;

        return {
            raw,
            rawStepIndex: Number.isFinite(rawStepIndex) ? Math.max(0, rawStepIndex) : null,
            stepIndex,
            stepTotal,
            kind: String(raw.kind || 'unknown'),
            gemBlessings: Array.isArray(raw.gem_blessings) ? raw.gem_blessings : [],
            gemBlessingUsers: Array.isArray(raw.gem_blessing_users) ? raw.gem_blessing_users : [],
            resolutionKind: raw.resolution_kind || null,
            outcome: String(raw.outcome || 'no_effect'),
            phase: String(raw.phase || ''),
            attackerSlotId,
            defenderSlotId,
            attackerActorId: raw.attacker_actor_id || null,
            defenderActorId: raw.defender_actor_id || raw.target_actor_id || null,
            targetActorId: raw.target_actor_id || null,
            notes: raw.notes || null,
            displayLabel: (raw.display_label !== undefined && raw.display_label !== null)
                ? String(raw.display_label)
                : null,
            timestamp: this._toNumber(raw.timestamp, Math.floor(Date.now() / 1000)),
            rolls,
            applied: {
                ...((raw.applied && typeof raw.applied === 'object') ? raw.applied : {}),
                fired_effects: raw.applied?.fired_effects || raw.fired_effects || [],
            },
            selfDestructed: Array.isArray(raw.self_destructed) ? raw.self_destructed : [],
            stacks: raw.stacks || {},
            outcomePayload: payload,
            damageEvents: Array.isArray(raw.damage_events) ? raw.damage_events : [],
            participants: Array.isArray(raw.participants) ? raw.participants : [],
            attackerSkillId: attackerSkillId ? String(attackerSkillId) : null,
            defenderSkillId: defenderSkillId ? String(defenderSkillId) : null,
            attackerSkillNameHint: attackerSkillName ? String(attackerSkillName) : null,
            defenderSkillNameHint: defenderSkillName ? String(defenderSkillName) : null
        };
    }

    _traceKey(step) {
        if (!step || typeof step !== 'object') return null;
        if (Number.isFinite(step.rawStepIndex)) return `raw:${step.rawStepIndex}`;
        if (Number.isFinite(step.stepIndex)) return `idx:${step.stepIndex}`;
        return [
            String(step.kind || ''),
            String(step.attackerSlotId || ''),
            String(step.defenderSlotId || ''),
            String(step.outcome || ''),
            String(step.timestamp || '')
        ].join('|');
    }

    _shouldHideStep(step) {
        if (!step || typeof step !== 'object') return false;
        const kind = String(step.kind || '');
        if (kind === 'redirect' || kind === 'redirect_cancelled_by_no_redirect' || kind === 'evade_insert') {
            return true;
        }
        const notes = String(step.notes || '');
        if (kind !== 'fizzle' || notes !== 'no_intent') return false;
        return !step.attackerSkillId;
    }

    _ingestTrace(state) {
        // A completed shared presentation is history, not resumable playback.
        // Rejoin snapshots retain the trace for logs/debugging, but must not
        // reopen the last result with a button the server can no longer accept.
        if (this._isResolvePresentationCompleted(state)) return;
        const trace = Array.isArray(state?.resolveTrace) ? state.resolveTrace : [];
        if (trace.length === 0) return;

        let appended = false;
        const sharedStepIndex = this._toNumber(
            state?.resolvePresentation?.current_step_index,
            0
        );
        const hasCurrentPrelude = trace.some((raw, index) => raw.kind === 'gem_blessing_prelude'
            && this._toNumber(raw.step_index, index) === sharedStepIndex);
        if (hasCurrentPrelude) {
            this._playQueue = this._playQueue.filter(step => !this._isIntroStep(step));
            if (this._isIntroStep(this._activeStep)) {
                this._stopPlayback();
                this._activeStep = null;
                this._renderedStepKey = null;
                this._waitingForFirstTrace = false;
            }
        }
        trace.forEach((raw, idx) => {
            const step = this._normalizeTraceEntry(raw, idx, state);
            if (Number.isFinite(step.rawStepIndex) && step.rawStepIndex < sharedStepIndex) return;
            if (this._shouldHideStep(step)) return;
            const key = this._traceKey(step);
            if (!key || this._traceSeen.has(key)) return;
            this._traceSeen.add(key);
            this._assignDisplayIndex(step, key);
            this._playQueue.push(step);
            appended = true;
        });

        if (appended) {
            this._playQueue.sort((a, b) => {
                const aIdx = this._toNumber(a?.stepIndex, 0);
                const bIdx = this._toNumber(b?.stepIndex, 0);
                if (aIdx !== bIdx) return aIdx - bIdx;
                return this._toNumber(a?.timestamp, 0) - this._toNumber(b?.timestamp, 0);
            });
        }

        // Keep denominator based on original planned steps (exclude virtual re-use steps).
        if (this._baseStepTotal <= 0) {
            const baseCandidate = trace
                .map((raw, idx) => this._normalizeTraceEntry(raw, idx, state))
                .filter((step) => !this._shouldHideStep(step) && !this._isIntroStep(step) && !this._isReuseStep(step))
                .map((step) => this._toNumber(step?.stepTotal, 0))
                .find((n) => n > 0);
            if (baseCandidate && Number.isFinite(baseCandidate)) {
                this._baseStepTotal = Math.max(1, Number(baseCandidate));
            }
        }
    }

    _assignDisplayIndex(step, key = null) {
        if (!step || this._isIntroStep(step) || step.kind === 'gem_blessing_prelude') return 0;
        const resolvedKey = key || this._traceKey(step);
        if (!resolvedKey) return 0;
        if (this._displayIndexByKey.has(resolvedKey)) {
            const existing = Number(this._displayIndexByKey.get(resolvedKey) || 0);
            step.displayIndex = existing;
            return existing;
        }
        this._displayIndexCursor += 1;
        this._displayIndexByKey.set(resolvedKey, this._displayIndexCursor);
        step.displayIndex = this._displayIndexCursor;
        return this._displayIndexCursor;
    }

    _onStateUpdated(state) {
        const isBattle = (state?.mode || 'battle') === 'battle';
        const phase = String(state?.phase || '');
        const traceLen = Array.isArray(state?.resolveTrace) ? state.resolveTrace.length : 0;
        const roundKey = this._roundStateKey(state);
        const hasRoundChanged = this._roundKey !== roundKey;
        if (hasRoundChanged || !isBattle) this._gemPortraits.clear();

        if (hasRoundChanged) {
            this._roundKey = roundKey;
            // 戦闘終結後の次の戦闘やルームリセットではラウンド番号が戻り、同じ battle_id で
            // 前と同じ識別子のラウンドが再び始まる。前の戦闘の演出表示・完了の記録は引き継がない。
            const roundNumber = Number(state?.round || 0);
            if (roundNumber < this._roundNumber) {
                this._introShownRounds.clear();
                this._completionEmittedRounds.clear();
            }
            this._roundNumber = roundNumber;
            this._stopPlayback();
            this._traceSeen.clear();
            this._displayIndexByKey.clear();
            this._displayIndexCursor = 0;
            this._presentedStepCount = 0;
            this._baseStepTotal = 0;
            this._playQueue = [];
            this._activeStep = null;
            this._renderedStepKey = null;
            this._waitingForAdvance = false;
            this._clearPendingAdvanceTimer();
            this._clearAdvanceRequestPending();
            this._pendingSyncedAdvanceCount = 0;
            this._roundSawResolvePhase = false;
            this._powerRevealSePlayedKeys.clear();
            this._resetNextMatchClock = false;
            this._waitingForFirstTrace = false;
            this._resolveStartPending = false;
            this._resolveOpeningRoundKey = null;
        }

        if (!isBattle) {
            this._stopPlayback();
            this._traceSeen.clear();
            this._displayIndexByKey.clear();
            this._displayIndexCursor = 0;
            this._presentedStepCount = 0;
            this._baseStepTotal = 0;
            this._playQueue = [];
            this._activeStep = null;
            this._renderedStepKey = null;
            this._introShownRounds.clear();
            this._waitingForAdvance = false;
            this._clearPendingAdvanceTimer();
            this._clearAdvanceRequestPending();
            this._pendingSyncedAdvanceCount = 0;
            this._roundSawResolvePhase = false;
            this._powerRevealSePlayedKeys.clear();
            this._resetNextMatchClock = false;
            this._waitingForFirstTrace = false;
            this._resolveStartPending = false;
            this._resolveOpeningRoundKey = null;
            this._removePanel();
            return;
        }

        const inResolve = this._isResolvePhase(phase);
        if (phase === 'select') this._preparePendingGemPortraits(state);
        if (inResolve) {
            this._resolveStartPending = false;
        }

        if (phase === 'round_end' && this._isResolvePresentationCompleted(state)) {
            const hadLocalPlayback = this._roundSawResolvePhase
                || this._presentedStepCount > 0
                || !!this._activeStep
                || this._playQueue.length > 0;
            this._stopPlayback();
            this._playQueue = [];
            this._activeStep = null;
            this._renderedStepKey = null;
            this._waitingForAdvance = false;
            this._waitingForFirstTrace = false;
            this._resolveOpeningRoundKey = null;
            if (hadLocalPlayback) this._emitResolveFlowCompleted(state);
            this._removePanel();
            return;
        }

        // If this round's resolve playback was already completed once,
        // do not replay it again when returning from exploration mode.
        const alreadyCompletedThisRound = !!roundKey && this._completionEmittedRounds.has(roundKey);
        if (alreadyCompletedThisRound && phase === 'round_end') {
            this._stopPlayback();
            this._playQueue = [];
            this._activeStep = null;
            this._renderedStepKey = null;
            this._waitingForAdvance = false;
            this._resolveOpeningRoundKey = null;
            this._removePanel();
            return;
        }

        // Defensive reset: when returning to select with an empty resolve trace,
        // stale denominator/index state must not survive within the same round.
        const isOpeningThisRound = this._resolveOpeningRoundKey === roundKey;
        if (phase === 'select' && traceLen === 0 && !this._resolveStartPending && !isOpeningThisRound) {
            this._traceSeen.clear();
            this._displayIndexByKey.clear();
            this._displayIndexCursor = 0;
            this._presentedStepCount = 0;
            this._baseStepTotal = 0;
            this._playQueue = [];
            this._activeStep = null;
            this._renderedStepKey = null;
            this._waitingForAdvance = false;
            this._clearPendingAdvanceTimer();
            this._clearAdvanceRequestPending();
            this._pendingSyncedAdvanceCount = 0;
            this._powerRevealSePlayedKeys.clear();
            this._resetNextMatchClock = false;
            this._waitingForFirstTrace = false;
        }

        const canPlayback = this._isPlaybackPhase(phase)
            || this._isResolvePresentationActive(phase)
            || isOpeningThisRound;
        if (inResolve) this._roundSawResolvePhase = true;
        if (this._isResolvePresentationActive(phase) && !this._introShownRounds.has(roundKey)) {
            this._resolveOpeningRoundKey = roundKey;
            this._enqueueBattleStartIntro(roundKey);
        }
        if (canPlayback || this._activeStep || this._playQueue.length > 0) {
            this._ingestTrace(state);
        }

        if (this._waitingForFirstTrace && this._playQueue.length > 0 && canPlayback) {
            this._waitingForFirstTrace = false;
            this._resolveOpeningRoundKey = null;
            this._activeStep = null;
            this._renderedStepKey = null;
            this._playNextStep({ forceLocalClock: true });
            return;
        }
        if (
            this._waitingForFirstTrace
            && phase === 'round_end'
            && this._playQueue.length === 0
            && this._isResolvePresentationCompleted(state)
        ) {
            this._waitingForFirstTrace = false;
            this._activeStep = null;
            this._renderedStepKey = null;
            this._emitResolveFlowCompleted(state);
            this._removePanel();
            return;
        }

        if (!this._activeStep && this._playQueue.length > 0 && canPlayback && !this._waitingForAdvance) {
            this._playNextStep();
            return;
        }

        if (!this._activeStep && this._playQueue.length === 0) {
            if (phase === 'round_end' && this._isResolvePresentationCompleted(state)) {
                this._emitResolveFlowCompleted(state);
                this._removePanel();
            } else if (!canPlayback) {
                this._removePanel();
            }
        } else if (this._activeStep) {
            this._renderStep(store.state || state);
        }
    }

    _clearTimers() {
        if (this._motionFrame !== null) {
            window.cancelAnimationFrame(this._motionFrame);
            this._motionFrame = null;
        }
        if (this._stepTimer) {
            clearTimeout(this._stepTimer);
            this._stepTimer = null;
        }
        if (this._tickTimer) {
            clearInterval(this._tickTimer);
            this._tickTimer = null;
        }
    }

    _stopPlayback() {
        this._finishFx();
        this._clearTimers();
        this._stepStartedAt = 0;
        this._clearPendingAdvanceTimer();
        this._clearAdvanceRequestPending();
    }

    _drawMotion(panel = null, elapsedMs = null) {
        if (!this._activeStep || this._isIntroStep(this._activeStep) || this._activeStep.kind === 'gem_blessing_prelude') return;
        const shell = panel || document.getElementById(this._panelId);
        const elapsed = elapsedMs ?? Math.max(0, Date.now() - this._stepStartedAt);
        const level = typeof window !== 'undefined' && window.Fx?.getLevel ? window.Fx.getLevel() : 'normal';
        renderStageMotion(shell?.querySelector('.resolve-stage-canvas'), stageMotionAt(this._activeStep, elapsed / 1000,
            level));
        if (window.Fx && shell) {
            const step = this._activeStep, starts = resolveStageStarts(step);
            const plan = step.kind === 'fizzle' ? null : resolveOutcomePlan(this, step, store.state);
            renderStageStacks(shell.querySelector('.resolve-stage-canvas'), step, plan, elapsed / 1000 - starts.outcome,
                currentStageLayout(shell), level, starts.wait - starts.outcome);
        }
    }

    _startMotionPlayback() {
        if (typeof window === 'undefined' || typeof window.requestAnimationFrame !== 'function') return;
        const draw = () => {
            this._motionFrame = null;
            if (!this._activeStep || this._isIntroStep(this._activeStep)) return;
            this._drawMotion();
            this._motionFrame = window.requestAnimationFrame(draw);
        };
        this._motionFrame = window.requestAnimationFrame(draw);
    }

    _playNextStep({ forceLocalClock = false } = {}) {
        this._stopPlayback();
        this._waitingForAdvance = false;
        this._clearAdvanceRequestPending();
        if (this._playQueue.length === 0) {
            const stateNow = store?.state || {};
            if (this._isIntroStep(this._activeStep) && this._shouldWaitForFirstTrace(stateNow)) {
                this._waitingForFirstTrace = true;
                this._renderStep(stateNow);
                return;
            }
            const lastRenderedKey = this._renderedStepKey;
            this._activeStep = null;
            this._renderedStepKey = null;
            const phase = String(stateNow?.phase || '');
            const shouldHideIntroResidue = String(lastRenderedKey || '').includes('battle_start');
            if (phase === 'round_end' && this._isResolvePresentationCompleted(stateNow)) {
                this._emitResolveFlowCompleted(stateNow);
                this._removePanel();
            } else if (!this._isResolvePresentationActive(phase) || shouldHideIntroResidue) {
                this._removePanel();
            }
            return;
        }
        this._activeStep = this._playQueue.shift();
        const isIntroStep = this._isIntroStep(this._activeStep);
        if (!isIntroStep) this._resolveOpeningRoundKey = null;
        const isFirstPresentedMatch = !isIntroStep && this._presentedStepCount === 0;
        const resetVisibleClock = !isIntroStep
            && (isFirstPresentedMatch || forceLocalClock || this._resetNextMatchClock);
        if (this._activeStep && !this._isIntroStep(this._activeStep) && this._activeStep.kind !== 'gem_blessing_prelude') {
            this._resetNextMatchClock = false;
            this._presentedStepCount += 1;
            this._activeStep.presentedIndex = this._presentedStepCount;
        }
        this._renderedStepKey = null;
        const presentation = store?.state?.resolvePresentation || {};
        const sharedStepIndex = this._toNumber(presentation.current_step_index, -1);
        const activeRawIndex = this._toNumber(this._activeStep?.rawStepIndex, -2);
        const sharedStartedAt = this._toNumber(presentation.step_started_at, 0);
        const useSharedClock = !resetVisibleClock && sharedStartedAt > 0 && sharedStepIndex === activeRawIndex;
        // 途中参加は共有時計へ合流し、端末の時計より未来なら今に丸める。最初に見せる手順（前置きを含む）は端末の時計（B03）。
        this._stepStartedAt = useSharedClock ? Math.min(sharedStartedAt, Date.now()) : Date.now();
        this._renderStep(store.state || {});

        if (!this._isIntroStep(this._activeStep)) {
            this._startMotionPlayback();
            this._tickTimer = setInterval(() => {
                if (!this._activeStep) return;
                this._renderStep(store.state || {});
            }, 60);
        }

        const durationMs = this._stepDuration(this._activeStep);

        const elapsedMs = Math.max(0, Date.now() - this._stepStartedAt);
        const remainingMs = Math.max(0, durationMs - elapsedMs);
        this._stepTimer = setTimeout(() => {
            if (!this._activeStep) return;
            if (this._isIntroStep(this._activeStep)) {
                const stateNow = store?.state || {};
                if (this._playQueue.length === 0 && this._shouldWaitForFirstTrace(stateNow)) {
                    this._clearTimers();
                    this._waitingForFirstTrace = true;
                    this._renderStep(stateNow);
                    return;
                }
                this._stopPlayback();
                this._waitingForFirstTrace = false;
                this._activeStep = null;
                // The shared cursor starts before the local BATTLE START intro.
                // The first visible match must start its gauge when it appears.
                this._playNextStep({ forceLocalClock: true });
                return;
            }
            this._clearTimers();
            this._waitingForAdvance = true;
            this._renderStep(store.state || {});
            this._emitResolveFlowStepFinished(this._activeStep, store.state || {});
            this._scheduleAutoAdvanceIfNeeded(store.state || {});
            if (this._pendingSyncedAdvanceCount > 0) {
                this._pendingSyncedAdvanceCount -= 1;
                this._advanceToNextBySync();
            }
        }, remainingMs);
    }

    _advanceToNextBySync() {
        this._flushCurrentStepDeferredLogs();
        this._clearPendingAdvanceTimer();
        this._clearAdvanceRequestPending();
        this._waitingForAdvance = false;
        this._activeStep = null;
        this._renderedStepKey = null;
        // 次へ進む合図を受け取った瞬間を、端末の時計での開始にする（サーバーの時刻と直接引き算しない）。
        this._playNextStep({ forceLocalClock: true });
    }

    _onAdvanceRequested(evt) {
        if (evt && typeof evt.preventDefault === 'function') evt.preventDefault();
        if (evt && typeof evt.stopPropagation === 'function') evt.stopPropagation();
        if (!this._waitingForAdvance || !this._activeStep) return;
        const state = store.state || {};
        if (!this._canDriveResolveFlow(state)) return;
        if (this._advanceRequestPending) return;
        const payload = this._buildAdvanceRequestPayload(state);
        if (!payload.room_id) {
            return;
        }
        const sent = socketClient.sendResolveFlowAdvance(payload);
        if (!sent) {
            return;
        }
        this._markAdvanceRequestPending();
        this._renderStep(state);
    }

    _onAutoAdvanceToggle(evt) {
        const checked = !!(evt && evt.target && evt.target.checked);
        this._autoAdvanceEnabled = checked;
        if (!checked) {
            this._clearPendingAdvanceTimer();
            return;
        }
        this._scheduleAutoAdvanceIfNeeded(store.state || {});
    }

    _onClaimRequested(evt) {
        if (evt && typeof evt.preventDefault === 'function') evt.preventDefault();
        if (evt && typeof evt.stopPropagation === 'function') evt.stopPropagation();
        const state = store.state || {};
        if (!this._canClaimResolveFlow(state)) return;
        socketClient.sendResolveFlowClaim({
            room_id: this._resolveActiveRoomId(state),
            battle_id: state?.battle_id || null,
            round: this._toNumber(state?.round, 0)
        });
    }

    _onSyncedAdvanceSignal(payload) {
        const state = store.state || {};
        if (!this._matchesSyncedAdvanceSignal(payload, state)) return;
        const phase = String(state?.phase || '');
        if (!this._isResolvePhase(phase) && !this._activeStep && !this._waitingForAdvance) return;
        this._clearAdvanceRequestPending();
        if (this._waitingForAdvance && this._activeStep) {
            this._advanceToNextBySync();
            return;
        }
        this._pendingSyncedAdvanceCount = Math.min(1, this._pendingSyncedAdvanceCount + 1);
    }

    _removePanel() {
        this._finishFx();
        const panel = document.getElementById(this._panelId);
        if (panel) panel.remove();
        this._renderedStepKey = null;
    }

    _finishFx() {
        if (typeof window !== 'undefined' && typeof window.Fx?.finishAll === 'function' && typeof document !== 'undefined') {
            for (const host of this._fxHosts || []) window.Fx.finishAll(host);
            this._fxHosts?.clear();
            window.Fx.finishAll(document.getElementById(this._panelId));
        }
        this._lastStageKey = null;
    }

    _skillNameFromData(skillData) {
        if (!skillData || typeof skillData !== 'object') return null;
        const defaultNameKey = '\u30c7\u30d5\u30a9\u30eb\u30c8\u540d\u79f0';
        const jpNameKey = '\u540d\u79f0';
        const keys = ['name', defaultNameKey, 'skill_name', 'skillName', jpNameKey];
        for (const key of keys) {
            const value = skillData[key];
            if (value !== undefined && value !== null && String(value).trim()) {
                return String(value).trim();
            }
        }
        return null;
    }

    _parseSkillFromCommand(commandText) {
        const src = String(commandText || '').trim();
        if (!src) return { id: null, name: null };
        const m = src.match(/\u3010\s*([^\s\u3011]+)(?:\s+([^\u3011]+))?\s*\u3011/);
        if (!m) return { id: null, name: null };
        return {
            id: m[1] ? String(m[1]).trim() : null,
            name: m[2] ? String(m[2]).trim() : null
        };
    }

    _resolveSkillMeta(step, side) {
        const payload = step?.outcomePayload || {};
        const delegateSummary = (payload.delegate_summary && typeof payload.delegate_summary === 'object')
            ? payload.delegate_summary
            : {};
        const summaryRolls = (delegateSummary.rolls && typeof delegateSummary.rolls === 'object')
            ? delegateSummary.rolls
            : {};
        const rolls = step?.rolls || {};
        const ownCommand = side === 'attacker'
            ? (rolls.command || summaryRolls.command || '')
            : (rolls.command_b || summaryRolls.command_b || '');
        const parsed = this._parseSkillFromCommand(ownCommand);

        if (side === 'attacker') {
            const skillId = step?.attackerSkillId || payload.skill_id || this._intentSkillId(store.state || {}, step?.attackerSlotId) || parsed.id || null;
            const skillData = this._skillById(skillId);
            const skillName = step?.attackerSkillNameHint
                || this._skillNameFromData(payload.skill)
                || this._skillNameFromData(skillData)
                || parsed.name
                || skillId
                || '-';
            return { id: skillId || '-', name: skillName || '-' };
        }

        if (this._isOneSidedPresentation(step)) {
            return { id: '-', name: '-' };
        }

        const inferredIntentSkillId = this._intentSkillId(store.state || {}, step?.defenderSlotId);
        const defenderId = step?.defenderSkillId || inferredIntentSkillId || parsed.id || null;
        const defenderSkillData = this._skillById(defenderId);
        const defenderName = step?.defenderSkillNameHint
            || this._skillNameFromData(defenderSkillData)
            || parsed.name
            || defenderId
            || '-';
        return { id: defenderId || '-', name: defenderName || '-' };
    }

    _isOneSidedPresentation(step) {
        return isOneSidedPresentation(step);
    }

    _resolvePowerValues(step) {
        const rolls = step?.rolls || {};
        const attackerSnapshot = this._powerSnapshotForSide(step, 'attacker') || {};
        const defenderSnapshot = this._powerSnapshotForSide(step, 'defender') || {};
        const isOneSided = this._isOneSidedPresentation(step);
        let attackPower = (
            rolls.power_a ??
            rolls.attacker_power ??
            rolls.total_damage ??
            rolls.final_damage ??
            rolls.base_damage ??
            attackerSnapshot.final_power ??
            '-'
        );
        // One-sided flow should display the dice roll power (base), not post-effect total.
        if (isOneSided) {
            attackPower = (
                rolls.base_damage ??
                rolls.power_a ??
                rolls.attacker_power ??
                rolls.total_damage ??
                rolls.final_damage ??
                attackerSnapshot.final_power ??
                '-'
            );
        }

        let defensePower = rolls.power_b ?? rolls.defender_sum ?? defenderSnapshot.final_power ?? '-';
        if (isOneSided) defensePower = '-';
        return {
            attacker: String(attackPower),
            defender: String(defensePower)
        };
    }

    _powerSnapshotForSide(step, side) {
        const payload = step?.outcomePayload || {};
        const delegateSummary = (payload.delegate_summary && typeof payload.delegate_summary === 'object')
            ? payload.delegate_summary
            : {};
        const summaryRolls = (delegateSummary.rolls && typeof delegateSummary.rolls === 'object')
            ? delegateSummary.rolls
            : {};
        const rolls = (step?.rolls && typeof step.rolls === 'object') ? step.rolls : {};

        if (side === 'attacker') {
            const snapshot = rolls.power_snapshot_a || rolls.power_snapshot || summaryRolls.power_snapshot_a || summaryRolls.power_snapshot;
            return (snapshot && typeof snapshot === 'object') ? snapshot : null;
        }

        const snapshot = rolls.power_snapshot_b || summaryRolls.power_snapshot_b;
        return (snapshot && typeof snapshot === 'object') ? snapshot : null;
    }

    _isDiceDamageSource(sourceRaw) {
        return isDiceDamageSource(sourceRaw);
    }

    _commandForSide(step, side) {
        const payload = step?.outcomePayload || {};
        const delegateSummary = (payload.delegate_summary && typeof payload.delegate_summary === 'object')
            ? payload.delegate_summary
            : {};
        const summaryRolls = (delegateSummary.rolls && typeof delegateSummary.rolls === 'object')
            ? delegateSummary.rolls
            : {};
        const rolls = (step?.rolls && typeof step.rolls === 'object') ? step.rolls : {};
        return side === 'attacker'
            ? (rolls.command || summaryRolls.command || '')
            : (rolls.command_b || rolls.command_d || summaryRolls.command_b || summaryRolls.command_d || '');
    }

    _resolveRangeFromRolls(step, side) {
        const rolls = (step?.rolls && typeof step.rolls === 'object') ? step.rolls : {};
        const minCandidates = side === 'attacker'
            ? [rolls.min_damage_a, rolls.min_a, rolls.min_damage, rolls.min]
            : [rolls.min_damage_b, rolls.min_b, rolls.min_damage_d, rolls.min_d, rolls.min];
        const maxCandidates = side === 'attacker'
            ? [rolls.max_damage_a, rolls.max_a, rolls.max_damage, rolls.max]
            : [rolls.max_damage_b, rolls.max_b, rolls.max_damage_d, rolls.max_d, rolls.max];

        const pick = (arr) => {
            for (const v of arr) {
                const n = Number(v);
                if (Number.isFinite(n)) return n;
            }
            return null;
        };
        const min = pick(minCandidates);
        const max = pick(maxCandidates);
        if (!Number.isFinite(min) || !Number.isFinite(max)) return null;
        return { min, max };
    }

    _diceRangeFromCommand(commandText) {
        const raw = String(commandText || '').trim();
        if (!raw) return null;
        const cleaned = raw
            .replace(/\u3010[^\u3011]*\u3011/g, '')
            .replace(/\s+/g, '');
        if (!cleaned) return null;
        const terms = cleaned.match(/[+\-]?[^+\-]+/g);
        if (!terms || terms.length === 0) return null;

        let min = 0;
        let max = 0;
        let valid = false;
        for (let termRaw of terms) {
            if (!termRaw) continue;
            let sign = 1;
            if (termRaw[0] === '+') {
                termRaw = termRaw.slice(1);
            } else if (termRaw[0] === '-') {
                sign = -1;
                termRaw = termRaw.slice(1);
            }
            if (!termRaw) continue;

            const diceMatch = termRaw.match(/^(\d*)d(\d+)$/i);
            if (diceMatch) {
                const count = diceMatch[1] ? Number(diceMatch[1]) : 1;
                const faces = Number(diceMatch[2]);
                if (!Number.isFinite(count) || !Number.isFinite(faces) || count <= 0 || faces <= 0) return null;
                const tMin = count;
                const tMax = count * faces;
                if (sign > 0) {
                    min += tMin;
                    max += tMax;
                } else {
                    min -= tMax;
                    max -= tMin;
                }
                valid = true;
                continue;
            }

            if (/^\d+$/.test(termRaw)) {
                const v = Number(termRaw);
                if (!Number.isFinite(v)) return null;
                min += sign * v;
                max += sign * v;
                valid = true;
                continue;
            }
            return null;
        }
        if (!valid) return null;
        return { min, max };
    }

    _resolvePowerBounds(step) {
        return Object.fromEntries(['attacker', 'defender'].map(side => [side,
            (side === 'defender' && (this._isOneSidedPresentation(step) || step.kind === 'mass_summation')) ? null
                : this._resolveRangeFromRolls(step, side) || this._diceRangeFromCommand(this._commandForSide(step, side))
        ]));
    }

    _resolvePowerRanges(step) {
        return Object.fromEntries(Object.entries(this._resolvePowerBounds(step)).map(([side, range]) =>
            [side, range ? `${range.min}~${range.max}` : '-']));
    }

    _collectDamageSummary(step, state) {
        const bucket = new Map();
        const pushDamage = (targetIdRaw, amountRaw, sourceRaw = '', forcedKind = null) => {
            const amount = this._toNumber(amountRaw, 0);
            if (amount <= 0) return;
            const targetId = String(targetIdRaw || '');
            const key = targetId || 'unknown';
            if (!bucket.has(key)) {
                bucket.set(key, { targetId, total: 0, dice: 0, effect: 0, details: [] });
            }
            const row = bucket.get(key);
            row.total += amount;
            const source = String(sourceRaw || '').trim();
            const kind = forcedKind || (this._isDiceDamageSource(source) ? 'dice' : 'effect');
            const normalizedSource = source.toLowerCase().includes('mass_summation_delta')
                ? '合計ダメージ'
                : (source || (kind === 'dice' ? 'ダイスダメージ' : 'キーワード効果ダメージ'));
            row.details.push({ source: normalizedSource, amount, kind });
            if (kind === 'dice') row.dice += amount;
            else row.effect += amount;
        };

        const applied = step?.applied || {};
        const appliedDamage = Array.isArray(applied.damage) ? applied.damage : [];
        const massDamage = Array.isArray(step?.damageEvents) ? step.damageEvents : [];
        const allDamageRows = [];
        appliedDamage.forEach((d) => {
            if (!d || typeof d !== 'object') return;
            allDamageRows.push({
                target_id: d.target_id,
                amount: d.hp ?? d.amount ?? 0,
                source: d.source || ''
            });
        });
        massDamage.forEach((d) => {
            if (!d || typeof d !== 'object') return;
            allDamageRows.push({
                target_id: d.target_id,
                amount: d.hp ?? d.amount ?? 0,
                source: d.damage_type || d.source || ''
            });
        });

        const kind = String(step?.kind || '');
        const rolls = step?.rolls || {};
        const baseRoll = this._toNumber(rolls.base_damage, 0);
        if ((kind === 'clash' || (kind === 'mass_individual' && step.resolutionKind === 'clash')) && allDamageRows.length > 0) {
            const outcome = String(step?.outcome || '');
            const powerA = this._toNumber(rolls.power_a, 0);
            const powerB = this._toNumber(rolls.power_b, 0);
            let primaryTargetId = '';
            let primaryDice = 0;
            if (outcome === 'attacker_win') {
                primaryTargetId = String(step?.defenderActorId || step?.targetActorId || allDamageRows[0]?.target_id || '');
                primaryDice = powerA;
            } else if (outcome === 'defender_win') {
                primaryTargetId = String(step?.attackerActorId || allDamageRows[0]?.target_id || '');
                primaryDice = powerB;
            }
            let primaryTotal = 0;
            const secondary = [];
            allDamageRows.forEach((row) => {
                const targetId = String(row?.target_id || '');
                const amount = this._toNumber(row?.amount, 0);
                if (amount <= 0) return;
                if (primaryTargetId && targetId === primaryTargetId) primaryTotal += amount;
                else secondary.push(row);
            });
            if (primaryTotal > 0) {
                const dicePart = Math.min(Math.max(0, primaryDice), primaryTotal);
                const effectPart = Math.max(0, primaryTotal - dicePart);
                if (dicePart > 0) pushDamage(primaryTargetId, dicePart, 'ダイスダメージ', 'dice');
                if (effectPart > 0) pushDamage(primaryTargetId, effectPart, 'キーワード効果ダメージ', 'effect');
            }
            secondary.forEach((row) => {
                pushDamage(row.target_id, row.amount, row.source || 'キーワード効果ダメージ', 'effect');
            });
        } else if (this._isOneSidedPresentation(step) && allDamageRows.length > 0) {
            const primaryTargetId = String(
                step?.targetActorId || step?.defenderActorId || allDamageRows[0]?.target_id || ''
            );
            let primaryTotal = 0;
            const secondary = [];
            allDamageRows.forEach((row) => {
                const targetId = String(row?.target_id || '');
                const amount = this._toNumber(row?.amount, 0);
                if (amount <= 0) return;
                if (targetId === primaryTargetId) primaryTotal += amount;
                else secondary.push(row);
            });
            if (primaryTotal > 0) {
                const dicePart = Math.min(baseRoll, primaryTotal);
                const effectPart = Math.max(0, primaryTotal - dicePart);
                if (dicePart > 0) pushDamage(primaryTargetId, dicePart, 'ダイスダメージ', 'dice');
                if (effectPart > 0) pushDamage(primaryTargetId, effectPart, 'キーワード効果ダメージ', 'effect');
            }
            secondary.forEach((row) => {
                pushDamage(row.target_id, row.amount, row.source || 'キーワード効果ダメージ', 'effect');
            });
        } else {
            allDamageRows.forEach((row) => {
                pushDamage(row.target_id, row.amount, row.source || '');
            });
        }

        const entries = Array.from(bucket.values());
        const total = entries.reduce((sum, row) => sum + this._toNumber(row.total, 0), 0);
        const diceTotal = entries.reduce((sum, row) => sum + this._toNumber(row.dice, 0), 0);
        const effectTotal = entries.reduce((sum, row) => sum + this._toNumber(row.effect, 0), 0);
        return {
            entries,
            total,
            text: total > 0 ? `${total}` : '\u30c0\u30e1\u30fc\u30b8\u306a\u3057',
            diceTotal,
            effectTotal
        };
    }

    _outcomeHeadline(step, attackerName, defenderName) {
        const kind = String(step?.kind || '');
        if (this._isOneSidedPresentation(step)) {
            return `${attackerName} 勝利`;
        }
        const outcome = String(step?.outcome || 'no_effect');
        if (outcome === 'attacker_win') return `${attackerName} \u52dd\u5229`;
        if (outcome === 'defender_win') {
            if (kind === 'mass_summation') return '\u9632\u885b\u5074\u52dd\u5229';
            return `${defenderName} \u52dd\u5229`;
        }
        if (outcome === 'draw') return '\u5f15\u304d\u5206\u3051';
        return '\u52b9\u679c\u306a\u3057';
    }

    _ensurePanel(host) {
        let panel = document.getElementById(this._panelId);
        if (!panel) {
            panel = document.createElement('div');
            panel.id = this._panelId;
            panel.dataset.theme = 'stage';
            panel.className = 'resolve-flow-panel';
            panel.innerHTML = `
                <div class="resolve-flow-overlay"></div>
                <div class="resolve-flow-content"></div>
            `;
            host.appendChild(panel);
        }
        if (!panel.querySelector('.resolve-flow-content')) {
            panel.innerHTML = `
                <div class="resolve-flow-overlay"></div>
                <div class="resolve-flow-content"></div>
            `;
            this._renderedStepKey = null;
        }
        return panel;
    }

    _panelContent(panel) {
        return panel?.querySelector('.resolve-flow-content') || null;
    }

    _isIntroStep(step) {
        return String(step?.kind || '') === 'battle_start';
    }

    _isReuseStep(step) {
        if (!step || typeof step !== 'object') return false;
        const slotId = String(step.attackerSlotId || '');
        if (slotId.includes('__EX')) return true;
        const label = String(step.displayLabel || '').trim();
        return /(?:^|-)EX\d*$/.test(label);
    }

    _enqueueBattleStartIntro(roundKey) {
        if (!roundKey) return;
        if (this._introShownRounds.has(roundKey)) return;
        this._introShownRounds.add(roundKey);
        this._resetNextMatchClock = true;
        this._playQueue.push({
            kind: 'battle_start',
            outcome: 'no_effect',
            stepIndex: -1,
            stepTotal: 0,
            timestamp: Math.floor(Date.now() / 1000),
            notes: null
        });
        this._playQueue.sort((a, b) => {
            const aIntro = this._isIntroStep(a) ? 0 : 1;
            const bIntro = this._isIntroStep(b) ? 0 : 1;
            if (aIntro !== bIntro) return aIntro - bIntro;
            const aIdx = this._toNumber(a?.stepIndex, 0);
            const bIdx = this._toNumber(b?.stepIndex, 0);
            if (aIdx !== bIdx) return aIdx - bIdx;
            return this._toNumber(a?.timestamp, 0) - this._toNumber(b?.timestamp, 0);
        });
    }

    _renderStep(state) {
        const host = document.getElementById('map-viewport');
        if (!host) {
            this._removePanel();
            return;
        }
        if (!this._activeStep) {
            this._removePanel();
            return;
        }

        const step = this._activeStep;
        const stepKey = this._traceKey(step) || `fallback:${String(step.kind || 'unknown')}:${String(step.stepIndex ?? '')}`;

        if (this._isIntroStep(step)) {
            const panelIntro = this._ensurePanel(host);
            const contentIntro = this._panelContent(panelIntro);
            if (!contentIntro) return;
            panelIntro.className = 'resolve-flow-panel intro stage-impact';
            if (this._renderedStepKey !== stepKey) {
                contentIntro.innerHTML = `
                    <div class="resolve-flow-intro-card">
                        <div class="resolve-flow-intro-main">\u6226\u95d8\u958b\u59cb</div>
                        <div class="resolve-flow-intro-sub">BATTLE START</div>
                    </div>
                `;
                this._renderedStepKey = stepKey;
            }
            const introSub = panelIntro.querySelector('.resolve-flow-intro-sub');
            if (introSub) {
                introSub.textContent = this._waitingForFirstTrace ? 'RESOLVING...' : 'BATTLE START';
            }
            return;
        }

        const elapsed = Math.max(0, Date.now() - this._stepStartedAt);
        const durationMs = this._stepDuration(step);
        const progress = Math.round(Math.max(0, Math.min(1, elapsed / durationMs)) * 100);
        const revealStage = this._revealStageByElapsed(elapsed, step);
        this._tryPlayPowerRevealSe(stepKey, revealStage);
        const stepNum = Number(step.presentedIndex) > 0 ? step.presentedIndex
            : Number(step.displayIndex) > 0 ? step.displayIndex : Math.max(1, Number(step.stepIndex || 0) + 1);
        const stepNumLabel = step.displayLabel?.trim() || String(stepNum);
        const kindClass = this._escape(String(step.kind || 'unknown'));
        const viewportWidth = typeof window !== 'undefined' ? window.innerWidth || 1180 : 1180;
        const viewportHeight = typeof window !== 'undefined' ? window.innerHeight || 900 : 900;

        const stateNow = store.state || state || {};
        const isGM = this._detectIsGM(stateNow);
        const canDrive = this._canDriveResolveFlow(stateNow);
        const canClaim = this._canClaimResolveFlow(stateNow);
        const controllerName = stateNow?.resolvePresentation?.controller_username || '進行役';
        const panel = this._ensurePanel(host);
        const panelContent = this._panelContent(panel);
        if (!panelContent) return;
        const layout = pickStageLayout((panel.clientWidth || viewportWidth) * 0.92, viewportHeight);
        const prelude = step.kind === 'gem_blessing_prelude';
        const stepBodyKey = `${stepKey}:${layout.width}`;
        panel.className = `resolve-flow-panel kind-${kindClass} reveal-${revealStage}${this._waitingForAdvance ? ' awaiting-advance' : ''}${canDrive ? ' can-drive' : ''}${isGM ? ' gm-user' : ''}`;
        if (this._renderedStepKey !== stepBodyKey) {
            this._finishFx();
            panelContent.innerHTML = prelude ? `<div class="resolve-gem-prelude">
                <div class="resolve-flow-waiting"></div>
                <button class="resolve-flow-next-btn">次へ</button>
                <label><input type="checkbox" class="resolve-flow-auto-checkbox">自動進行</label>
                <button class="resolve-flow-claim-btn">進行を引き継ぐ</button>
                </div>` : renderResolveStage(this, step, state, layout);
            this._renderedStepKey = stepBodyKey;
        }
        const number = panel.querySelector('.step-number');
        if (number) number.textContent = stepNumLabel;
        if (!prelude) {
            fitResolveStage(panel, layout, viewportWidth, viewportHeight);
            this._drawMotion(panel, elapsed);
        }

        const revealNode = panel.querySelector('.resolve-flow-reveal-stage');
        this._notifyStage(stepKey, revealStage, step);
        if (revealNode) {
            revealNode.textContent = this._revealLabel(revealStage);
        }
        const nextBtn = panel.querySelector('.resolve-flow-next-btn');
        if (nextBtn) {
            if (!nextBtn.dataset.bound) {
                nextBtn.dataset.bound = '1';
                nextBtn.addEventListener('click', (evt) => this._onAdvanceRequested(evt));
            }
            nextBtn.disabled = !(canDrive && this._waitingForAdvance) || this._advanceRequestPending;
        }
        const autoChk = panel.querySelector('.resolve-flow-auto-checkbox');
        if (autoChk) {
            if (!autoChk.dataset.bound) {
                autoChk.dataset.bound = '1';
                autoChk.addEventListener('change', (evt) => this._onAutoAdvanceToggle(evt));
            }
            autoChk.checked = !!this._autoAdvanceEnabled;
            autoChk.disabled = !canDrive;
        }
        const claimBtn = panel.querySelector('.resolve-flow-claim-btn');
        if (claimBtn) {
            if (!claimBtn.dataset.bound) {
                claimBtn.dataset.bound = '1';
                claimBtn.addEventListener('click', (evt) => this._onClaimRequested(evt));
            }
            claimBtn.style.display = canClaim ? '' : 'none';
        }
        const waitingNode = panel.querySelector('.resolve-flow-waiting');
        if (waitingNode) {
            waitingNode.textContent = this._waitingForAdvance
                ? (canDrive
                    ? (this._advanceRequestPending
                        ? '\u9032\u884c\u8981\u6c42\u9001\u4fe1\u4e2d...'
                        : this._autoAdvanceEnabled
                        ? `表示完了: ${resolveWaitMs(step, this._autoAdvanceDelayMs) / 1000}秒後に自動進行`
                        : '\u8868\u793a\u5b8c\u4e86: \u30dc\u30bf\u30f3\u3067\u6b21\u3078\u9032\u884c')
                    : `${controllerName}が進行するまで待機中`)
                : '';
        }
        this._scheduleAutoAdvanceIfNeeded(stateNow);
        const fill = panel.querySelector('.resolve-flow-timer .fill');
        if (fill) {
            fill.style.width = `${progress}%`;
        }
    }

    _render() {
        this._onStateUpdated(store.state || {});
    }
}

export { ResolveFlowPanel };
export const resolveFlowPanel = new ResolveFlowPanel();

if (typeof window !== 'undefined') {
    window.ResolveFlowPanelComponent = resolveFlowPanel;
}
